// Directly implementing stage 2's State Management Strategy section:
// server state (jobs) via React Query, client state (form) via useState

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useState } from 'react';

interface Job {
  _id: string;
  employerName: string;
  hourlyRate: number;
}

function JobsPage() {
  const queryClient = useQueryClient();
  const [newJobName, setNewJobName] = useState('');
  const [newJobRate, setNewJobRate] = useState('');

  const { data: jobs, isLoading, error } = useQuery<Job[]>({
    queryKey: ['jobs'],
    queryFn: () => fetch('/api/jobs').then((r) => {
      if (!r.ok) throw new Error('Failed to load jobs');
      return r.json();
    })
  });

  const createJob = useMutation({
    mutationFn: (newJob: { employerName: string; hourlyRate: number }) =>
      fetch('/api/jobs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newJob)
      }).then((r) => {
        if (!r.ok) throw new Error('Failed to create job');
        return r.json();
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['jobs'] }); // Module 16's
        // exact cache-invalidation pattern
      setNewJobName('');
      setNewJobRate('');
    }
  });

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    // CLIENT-SIDE validation - immediate UX feedback ONLY, never a
    // substitute for the backend's own, independent validation
    if (!newJobName.trim() || !newJobRate || Number(newJobRate) <= 0) {
      return;
    }
    createJob.mutate({ employerName: newJobName, hourlyRate: Number(newJobRate) });
  }

  if (isLoading) return <p>Loading jobs...</p>;
  if (error) return <p>Something went wrong loading your jobs.</p>;

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input value={newJobName} onChange={(e) => setNewJobName(e.target.value)} placeholder="Employer name" />
        <input value={newJobRate} onChange={(e) => setNewJobRate(e.target.value)} placeholder="Hourly rate" type="number" />
        <button type="submit" disabled={createJob.isPending}>Add Job</button>
      </form>
      <ul>
        {jobs?.map((job) => <li key={job._id}>{job.employerName} - ${job.hourlyRate}/hr</li>)}
      </ul>
    </div>
  );
}

