interface Client {
  _id: string;
  name: string;
  contactInfo: string;
}

function ClientsPage() {
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [contactInfo, setContactInfo] = useState('');

  const { data: clients, isLoading, error } = useQuery<Client[]>({
    queryKey: ['clients'],
    queryFn: () => fetch('/api/clients').then((r) => {
      if (!r.ok) throw new Error('Failed to load clients');
      return r.json();
    })
  });

  const createClient = useMutation({
    mutationFn: (newClient: { name: string; contactInfo: string }) =>
      fetch('/api/clients', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newClient)
      }).then((r) => {
        if (!r.ok) throw new Error('Failed to create client');
        return r.json();
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['clients'] });
      setName('');
      setContactInfo('');
    }
  });

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    // CLIENT-SIDE validation - UX feedback only; the backend
    // independently, fully re-validates this same data
    if (!name.trim()) return;
    createClient.mutate({ name, contactInfo });
  }

  if (isLoading) return <p>Loading...</p>;
  if (error) return <p>Something went wrong.</p>;

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Client name" />
        <input value={contactInfo} onChange={(e) => setContactInfo(e.target.value)} placeholder="Contact info" />
        <button type="submit">Add Client</button>
      </form>
      <ul>{clients?.map((c) => <li key={c._id}>{c.name}</li>)}</ul>
    </div>
  );
}

