// Repository layer - abstracts the actual database access
class JobRepository {
  async create(userId: string, employerName: string, hourlyRate: number) {
    const result = await jobsCollection.insertOne({ userId, employerName, hourlyRate, createdAt: new Date() });
    return { _id: result.insertedId, userId, employerName, hourlyRate };
  }
  async findAllForUser(userId: string) {
    return jobsCollection.find({ userId }).toArray();
  }
}

// Service layer - business logic and validation, completely
// independent of anything the frontend (stage 3) may have already checked
class JobService {
  constructor(private repo: JobRepository) {}

  async createJob(userId: string, employerName: unknown, hourlyRate: unknown) {
    // INDEPENDENT validation - imagining a hostile client sending
    // this request directly, with no relationship to stage 3 at all
    if (typeof employerName !== 'string' || employerName.trim().length === 0) {
      throw new ValidationError('employerName must be a non-empty string');
    }
    if (typeof hourlyRate !== 'number' || hourlyRate <= 0 || hourlyRate > 1000) {
      throw new ValidationError('hourlyRate must be a positive number under 1000');
    }
    return this.repo.create(userId, employerName.trim(), hourlyRate);
  }
}

// Controller layer - thin, handles only request/response
const jobService = new JobService(new JobRepository());

app.post('/api/jobs', requireAuth, async (req, res, next) => {
  try {
    const job = await jobService.createJob(req.userId, req.body.employerName, req.body.hourlyRate);
    res.status(201).json({ success: true, data: job });
  } catch (err) {
    next(err);
  }
});

app.get('/api/jobs', requireAuth, async (req, res, next) => {
  try {
    const jobs = await jobService.repo.findAllForUser(req.userId);
    res.json({ success: true, data: jobs });
  } catch (err) {
    next(err);
  }
});

