import { test, expect } from '@playwright/test';

test('a new user can sign up, add a job, log a shift, and see it on their dashboard', async ({ page }) => {
  // This SINGLE test covers the entire, genuinely critical journey -
  // if this breaks, the application is fundamentally non-functional
  // for any new user, regardless of how polished any individual
  // feature looks in isolation

  await page.goto('https://your-deployed-app.example.com/signup');
  await page.fill('input[name="email"]', 'e2e-test@example.com');
  await page.fill('input[name="password"]', 'TestPassword123');
  await page.click('button[type="submit"]');

  await expect(page).toHaveURL(/dashboard/);

  await page.click('text=Add Job');
  await page.fill('input[name="employerName"]', 'Coffee Shop');
  await page.fill('input[name="hourlyRate"]', '18');
  await page.click('button:has-text("Save Job")');

  await page.click('text=Log Shift');
  await page.selectOption('select[name="jobId"]', { label: 'Coffee Shop' });
  await page.fill('input[name="date"]', '2026-06-15');
  await page.fill('input[name="startTime"]', '09:00');
  await page.fill('input[name="endTime"]', '17:00');
  await page.click('button:has-text("Save Shift")');

  await page.goto('https://your-deployed-app.example.com/dashboard');
  await expect(page.locator('text=Coffee Shop')).toBeVisible();
  await expect(page.locator('text=8 hours')).toBeVisible(); // genuinely
    // verifying the actual, correct calculated result, not just that
    // some text exists on the page at all
});
